import { User, Classroom, EnrolledStudent, Role } from './types';

// Claves de almacenamiento
const KEYS = {
    USERS: 'school_users',
    CLASSROOMS: 'school_classrooms',
    STUDENTS: 'school_students'
};

// Datos iniciales para sembrar la BD si está vacía
const SEED_USERS: User[] = [
    { id: '1', username: 'admin', password: 'admin123', name: 'Director Principal', role: 'admin' },
    { id: '2', username: 'docente', password: 'docente123', name: 'Maestro Ejemplar', role: 'docente' }
];

class SchoolDatabase {

    constructor() {
        this.init();
    }

    // Inicializa la BD con datos por defecto si no existen
    private init() {
        if (!localStorage.getItem(KEYS.USERS)) {
            localStorage.setItem(KEYS.USERS, JSON.stringify(SEED_USERS));
        }
        if (!localStorage.getItem(KEYS.CLASSROOMS)) {
            localStorage.setItem(KEYS.CLASSROOMS, JSON.stringify([]));
        }
        if (!localStorage.getItem(KEYS.STUDENTS)) {
            localStorage.setItem(KEYS.STUDENTS, JSON.stringify([]));
        }
    }

    // --- USERS ---
    getUsers(): User[] {
        const data = localStorage.getItem(KEYS.USERS);
        return data ? JSON.parse(data) : [];
    }

    addUser(user: User): User[] {
        const users = this.getUsers();
        const newUsers = [...users, user];
        this.save(KEYS.USERS, newUsers);
        return newUsers;
    }

    deleteUser(id: string): User[] {
        const users = this.getUsers().filter(u => u.id !== id);
        this.save(KEYS.USERS, users);
        return users;
    }

    updateUserPassword(id: string, newPass: string): User[] {
        const users = this.getUsers().map(u => u.id === id ? { ...u, password: newPass } : u);
        this.save(KEYS.USERS, users);
        return users;
    }

    // --- CLASSROOMS ---
    getClassrooms(): Classroom[] {
        const data = localStorage.getItem(KEYS.CLASSROOMS);
        return data ? JSON.parse(data) : [];
    }

    addClassroom(classroom: Classroom): Classroom[] {
        const classes = this.getClassrooms();
        const newClasses = [...classes, classroom];
        this.save(KEYS.CLASSROOMS, newClasses);
        return newClasses;
    }

    deleteClassroom(id: string): Classroom[] {
        const classes = this.getClassrooms().filter(c => c.id !== id);
        this.save(KEYS.CLASSROOMS, classes);
        // Opcional: Podríamos borrar estudiantes en cascada aquí
        return classes;
    }

    // --- STUDENTS ---
    getStudents(): EnrolledStudent[] {
        const data = localStorage.getItem(KEYS.STUDENTS);
        return data ? JSON.parse(data) : [];
    }

    addStudent(student: EnrolledStudent): EnrolledStudent[] {
        const students = this.getStudents();
        const newStudents = [...students, student];
        this.save(KEYS.STUDENTS, newStudents);
        return newStudents;
    }

    deleteStudent(id: string): EnrolledStudent[] {
        const students = this.getStudents().filter(s => s.id !== id);
        this.save(KEYS.STUDENTS, students);
        return students;
    }

    updateStudentGrade(id: string, grade: number | null): EnrolledStudent[] {
        const students = this.getStudents().map(s => s.id === id ? { ...s, grade } : s);
        this.save(KEYS.STUDENTS, students);
        return students;
    }

    // --- UTILS ---
    private save(key: string, data: any) {
        localStorage.setItem(key, JSON.stringify(data));
    }

    resetDatabase() {
        localStorage.removeItem(KEYS.USERS);
        localStorage.removeItem(KEYS.CLASSROOMS);
        localStorage.removeItem(KEYS.STUDENTS);
        this.init();
    }
}

export const db = new SchoolDatabase();

