type ViewMode = 'landing' | 'login' | 'student';

const App: React.FC = () => {
    // Database State
    const [users, setUsers] = useState<User[]>([]);
    const [classrooms, setClassrooms] = useState<Classroom[]>([]);
    const [students, setStudents] = useState<EnrolledStudent[]>([]);

    // Session State
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [viewMode, setViewMode] = useState<ViewMode>('landing');
    const [loginError, setLoginError] = useState('');

    // Load Data on Mount from "Database"
    useEffect(() => {
        setUsers(db.getUsers());
        setClassrooms(db.getClassrooms());
        setStudents(db.getStudents());
    }, []);

    // Actions
    const handleLogin = (u: string, p: string) => {
        // En una app real, esto sería una llamada asíncrona a la API
        const user = users.find(user => user.username === u && user.password === p);
        if (user) {
            setCurrentUser(user);
            setLoginError('');
        } else {
            setLoginError('Credenciales incorrectas');
        }
    };

    const handleLogout = () => {
        setCurrentUser(null);
        setLoginError('');
        setViewMode('landing');
    }

    const handleResetData = () => {
        if(window.confirm("¿Estás seguro de restaurar los datos de prueba? Se borrarán todos los usuarios y salones creados.")){
            db.resetDatabase();
            window.location.reload();
        }
    }

    // Estas acciones actualizan la BD y luego el estado local para refrescar la UI
    const dbActions = {
        addUser: (user: User) => setUsers(db.addUser(user)),
        deleteUser: (id: string) => setUsers(db.deleteUser(id)),
        resetPassword: (id: string, newPass: string) => setUsers(db.updateUserPassword(id, newPass)),

        addClassroom: (cls: Classroom) => setClassrooms(db.addClassroom(cls)),
        deleteClassroom: (id: string) => setClassrooms(db.deleteClassroom(id)),

        addStudent: (student: EnrolledStudent) => setStudents(db.addStudent(student)),
        deleteStudent: (id: string) => setStudents(db.deleteStudent(id)),
        updateGrade: (id: string, grade: number | null) => setStudents(db.updateStudentGrade(id, grade))
    };

    return (
        <div className="min-h-screen bg-slate-900 text-slate-100 p-4 sm:p-6 lg:p-8">
            <div className="max-w-6xl mx-auto">
                <header className="flex justify-between items-center mb-8 border-b border-slate-800 pb-6">
                    <div>
                        <h1 className="text-3xl font-extrabold tracking-tight text-white sm:text-4xl flex items-center gap-2">
                             <HomeIcon />
                             Sistema Escolar
                        </h1>
                        <p className="mt-1 text-lg text-slate-400">Secundaria Num. 5</p>
                    </div>
                    {currentUser && (
                        <div className="flex items-center gap-4">
                            <div className="text-right hidden sm:block">
                                <p className="font-bold text-white">{currentUser.name}</p>
                                <p className="text-xs text-slate-400 uppercase">{currentUser.role}</p>
                            </div>
                            <button onClick={handleLogout} className="bg-slate-800 p-2 rounded-full hover:bg-slate-700 text-slate-400 hover:text-white transition-colors" title="Cerrar Sesión">
                                <LogoutIcon />
                            </button>
                        </div>
                    )}
                </header>

                <main>
                    {!currentUser && viewMode === 'landing' && (
                        <LandingScreen 
                            onSelectStudent={() => setViewMode('student')}
                            onSelectTeacher={() => setViewMode('login')}
                        />
                    )}

                    {!currentUser && viewMode === 'student' && (
                        <StudentPortal 
                            classrooms={classrooms}
                            students={students}
                            onBack={() => setViewMode('landing')}
                        />
                    )}

                    {!currentUser && viewMode === 'login' && (
                        <LoginScreen 
                            onLogin={handleLogin} 
                            error={loginError} 
                            onReset={handleResetData} 
                            onBack={() => setViewMode('landing')}
                        />
                    )}

                    {currentUser?.role === 'admin' && (
                        <AdminDashboard 
                            users={users} 
                            classrooms={classrooms} 
                            students={students} 
                            actions={dbActions} 
                        />
                    )}

                    {currentUser?.role === 'docente' && (
                        <TeacherDashboard 
                            currentUser={currentUser}
                            classrooms={classrooms}
                            students={students}
                            actions={dbActions} 
                        />
                    )}
                </main>
                 <footer className="text-center mt-12 text-slate-500 text-sm">
                    <p>Creado por Pablo Soriano.</p>
                </footer>
            </div>
        </div>
    );
};

