import { User, Classroom, EnrolledStudent } from './types';

// Claves de almacenamiento local (mientras conectas la BD real)
const KEYS = {
    USERS: 'school_users',
    CLASSROOMS: 'school_classrooms',
    STUDENTS: 'school_students'
};

// Datos iniciales
const SEED_USERS: User[] = [
    { id: '1', username: 'admin', password: 'admin123', name: 'Director Principal', role: 'admin' },
    { id: '2', username: 'docente', password: 'docente123', name: 'Maestro Ejemplar', role: 'docente' }
];

// Simula un retraso de red (como si fuera una base de datos real en la nube)
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

class SchoolDatabase {

    constructor() {
        this.init();
    }

    private init() {
        if (!localStorage.getItem(KEYS.USERS)) {
            localStorage.setItem(KEYS.USERS, JSON.stringify(SEED_USERS));
        }
        if (!localStorage.getItem(KEYS.CLASSROOMS)) {
            localStorage.setItem(KEYS.CLASSROOMS, JSON.stringify([]));
        }
        if (!localStorage.getItem(KEYS.STUDENTS)) {
            localStorage.setItem(KEYS.STUDENTS, JSON.stringify([]));
        }
    }

    // --- USERS ---

    // NOTA: Todos los métodos ahora son ASYNC para imitar una base de datos real
    async getUsers(): Promise<User[]> {
        await delay(300); // Simular latencia de red
        const data = localStorage.getItem(KEYS.USERS);
        return data ? JSON.parse(data) : [];
    }

    async addUser(user: User): Promise<User[]> {
        await delay(300);
        const users = await this.getUsers();
        const newUsers = [...users, user];
        this.save(KEYS.USERS, newUsers);
        return newUsers;
    }

    async deleteUser(id: string): Promise<User[]> {
        await delay(300);
        const users = await this.getUsers();
        const filtered = users.filter(u => u.id !== id);
        this.save(KEYS.USERS, filtered);
        return filtered;
    }

    async updateUserPassword(id: string, newPass: string): Promise<User[]> {
        await delay(300);
        const users = await this.getUsers();
        const updated = users.map(u => u.id === id ? { ...u, password: newPass } : u);
        this.save(KEYS.USERS, updated);
        return updated;
    }

    // --- CLASSROOMS ---
    async getClassrooms(): Promise<Classroom[]> {
        await delay(300);
        const data = localStorage.getItem(KEYS.CLASSROOMS);
        return data ? JSON.parse(data) : [];
    }

    async addClassroom(classroom: Classroom): Promise<Classroom[]> {
        await delay(300);
        const classes = await this.getClassrooms();
        const newClasses = [...classes, classroom];
        this.save(KEYS.CLASSROOMS, newClasses);
        return newClasses;
    }

    async deleteClassroom(id: string): Promise<Classroom[]> {
        await delay(300);
        const classes = await this.getClassrooms();
        const filtered = classes.filter(c => c.id !== id);
        this.save(KEYS.CLASSROOMS, filtered);
        return filtered;
    }

    // --- STUDENTS ---
    async getStudents(): Promise<EnrolledStudent[]> {
        await delay(300);
        const data = localStorage.getItem(KEYS.STUDENTS);
        return data ? JSON.parse(data) : [];
    }

    async addStudent(student: EnrolledStudent): Promise<EnrolledStudent[]> {
        await delay(300);
        const students = await this.getStudents();
        const newStudents = [...students, student];
        this.save(KEYS.STUDENTS, newStudents);
        return newStudents;
    }

    async deleteStudent(id: string): Promise<EnrolledStudent[]> {
        await delay(300);
        const students = await this.getStudents();
        const filtered = students.filter(s => s.id !== id);
        this.save(KEYS.STUDENTS, filtered);
        return filtered;
    }

    async updateStudentGrade(id: string, grade: number | null): Promise<EnrolledStudent[]> {
        await delay(300);
        const students = await this.getStudents();
        const updated = students.map(s => s.id === id ? { ...s, grade } : s);
        this.save(KEYS.STUDENTS, updated);
        return updated;
    }

    // --- UTILS ---
    private save(key: string, data: any) {
        localStorage.setItem(key, JSON.stringify(data));
    }

    async resetDatabase() {
        await delay(500);
        localStorage.removeItem(KEYS.USERS);
        localStorage.removeItem(KEYS.CLASSROOMS);
        localStorage.removeItem(KEYS.STUDENTS);
        this.init();
    }
}

export const db = new SchoolDatabase();

