                    icon={<AttendanceIcon />}
                    />
                    <Tab 
                    label="Evaluación Alumno" 
                    isActive={activeTab === 'student'} 
                    onClick={() => setActiveTab('student')}
                    icon={<StudentIcon />}
                    />
                    <Tab 
                    label="Estadísticas Grupo" 
                    isActive={activeTab === 'group'} 
                    onClick={() => setActiveTab('group')} 
                    icon={<GroupIcon />}
                    />
