                                    value={newClass.teacherId}
                                    onChange={e => setNewClass({...newClass, teacherId: e.target.value})}
                                >
                                    <option value="">Seleccione un docente...</option>
                                    {teachers.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
