                        </div>
                    </Card>
                    <Card>
                        <h3 className="text-xl font-bold mb-4 text-sky-400">Salones Activos</h3>
                        <div className="space-y-2 max-h-96 overflow-y-auto">
                            {classrooms.map(cls => {
